/**
 * Account states that end a delivery without a platform bug.
 * The reason comes from the delivery message. Metric tags stay this closed set.
 */
const USAGE_LIMIT_PHRASES = [
    "reached its usage limit",
    "reached your usage limit",
    "reached the usage limit",
    // Billing titles insert "monthly", or say "hit" instead of "reached".
    "monthly usage limit",
    "hit your usage limit",
    // Prepaid wallets: the additional-usage cap or an exhausted balance.
    "monthly additional usage limit",
    "additional usage is off",
    "prepaid balance is used up",
    // A team's spend reached the budget its organization set.
    "team budget limit reached",
    // The deployment's service account reached the limit a team admin set for
    // the billing period. Retrying cannot clear it.
    "service account spend limit reached",
];
const UNPAID_INVOICE_PHRASES = ["unpaid invoice"];
export function classifyExpectedDeliveryFailure(message) {
    if (message === undefined || message.length === 0) {
        return undefined;
    }
    const text = message.toLowerCase();
    if (UNPAID_INVOICE_PHRASES.some((phrase) => text.includes(phrase))) {
        return "unpaid_invoice";
    }
    if (USAGE_LIMIT_PHRASES.some((phrase) => text.includes(phrase))) {
        return "usage_limit";
    }
    return undefined;
}
